/* Accuracy check: the browser JS engine (js/engine.js) against the
 * proven JPL DE440 reference values for the fixed cases N1-N10.
 *
 * The reference (tools/reference-n1-n10.json) was generated by the
 * project's Python prototype (engine-proof/astro_engine.py), which the
 * ENGINE-PROOF harness verified against Swiss Ephemeris on 100 charts
 * (worst difference 0.21 arc-minutes). So this check measures the JS
 * engine against JPL-grade values.
 *
 * Run:  node tools/check-engine.js
 * Tolerances for this v1 stage: signs exact on every planet; degrees
 * within 5 arc-minutes for planets, 10 for the Moon. Asc/MC/cusps are
 * reported too (same formulas ported; expected near-exact apart from
 * the sidereal-time convention difference noted in ENGINE-PROOF.md).
 */
"use strict";
const Engine = require("../js/engine.js");
const ref = require("./reference-n1-n10.json");

const TOL_PLANET = 5, TOL_MOON = 10;
function diffArcmin(a, b) {
  let d = Math.abs(a - b) % 360;
  if (d > 180) d = 360 - d;
  return d * 60;
}

let signFlips = 0, tolMisses = [];
const worst = {};
let ascWorst = 0, mcWorst = 0, cuspWorst = 0;

for (const c of ref) {
  const got = Engine.computeChart(c.date, c.time, c.lat, c.lon, c.tz);
  const line = [c.id];
  // time resolution must match the proven engine exactly
  if (got.resolved.offsetLabel !== c.offset_used) line.push("OFFSET " + got.resolved.offsetLabel + " != " + c.offset_used);
  if (got.resolved.status !== c.time_status) line.push("STATUS " + got.resolved.status + " != " + c.time_status);
  if ((got.houseSystem || null) !== c.house_system) line.push("HOUSES " + got.houseSystem + " != " + c.house_system);
  for (const p of Engine.PLANETS) {
    const d = diffArcmin(got.planets[p], c.planets[p]);
    worst[p] = Math.max(worst[p] || 0, d);
    if (Engine.signOf(got.planets[p]) !== Engine.signOf(c.planets[p])) {
      signFlips++; line.push("SIGN FLIP " + p + ": " + Engine.formatPosition(got.planets[p]) + " vs " + Engine.formatPosition(c.planets[p]));
    }
    const tol = p === "Moon" ? TOL_MOON : TOL_PLANET;
    if (d > tol) tolMisses.push(c.id + " " + p + " off by " + d.toFixed(2) + "'");
  }
  if (c.asc !== null && got.asc !== null) ascWorst = Math.max(ascWorst, diffArcmin(got.asc, c.asc));
  if (c.mc !== null && got.mc !== null) mcWorst = Math.max(mcWorst, diffArcmin(got.mc, c.mc));
  if (c.cusps && got.cusps) {
    for (let i = 0; i < 12; i++) cuspWorst = Math.max(cuspWorst, diffArcmin(got.cusps[i], c.cusps[i]));
  }
  if (c.moon_day_range && got.moonDayRange) {
    for (const t of ["00:00", "12:00", "23:59"]) {
      const d = diffArcmin(got.moonDayRange[t], c.moon_day_range[t]);
      worst.Moon = Math.max(worst.Moon, d);
      if (d > TOL_MOON) tolMisses.push(c.id + " Moon@" + t + " off by " + d.toFixed(2) + "'");
    }
  }
  console.log(line.join("  "));
}

console.log("\nWorst differences vs the JPL DE440 reference (arc-minutes):");
for (const p of Engine.PLANETS) console.log("  " + p.padEnd(8), (worst[p] || 0).toFixed(3) + "'");
console.log("  Asc worst " + ascWorst.toFixed(3) + "'   MC worst " + mcWorst.toFixed(3) + "'   cusp worst " + cuspWorst.toFixed(3) + "'");
console.log("Sign flips: " + signFlips);
console.log("Tolerance misses (" + TOL_PLANET + "' planets / " + TOL_MOON + "' Moon): " + tolMisses.length);
for (const m of tolMisses) console.log("  MISS " + m);
console.log(signFlips === 0 && tolMisses.length === 0 ? "\nVERDICT: PASS" : "\nVERDICT: FAIL");
